// Runtime for Claude Code Workflow scripts generated by tools/orchestrator/workflow.ts.
// The generator places `const CONFIG = {...}` above this text. Edit the config, not generated scripts.

const ROOT = (args && typeof args === 'object' && typeof args.root === 'string' && args.root) || CONFIG.root
if (!ROOT) throw new Error('Pass the repository root as Workflow args: { root: "/absolute/path" }')
const VARS = { root: ROOT }
const fill = text => text.replace(/\{\{([A-Za-z][A-Za-z0-9_]*)\}\}/g, (match, key) => (key in VARS ? VARS[key] : match))
for (const [key, value] of Object.entries(CONFIG.vars)) VARS[key] = fill(value)

const SHARED = fill(`Repository: {{root}}. Follow its AGENTS.md and the rules below.
If docs/project-memory/index.md exists, read the entries relevant to your task and confirm them against current source. Do not edit docs/project-memory; put proposed memory corrections in your report summary as sentences starting "Memory:".

${CONFIG.shared}`)

const STRINGS = { type: 'array', items: { type: 'string' } }
const IMPL_PROPERTIES = {
  status: { type: 'string', enum: ['done', 'partial', 'stopped'] },
  summary: { type: 'string' },
  filesChanged: STRINGS,
  testsAddedOrChanged: STRINGS,
  gates: { type: 'string' },
  focusedTests: { type: 'string' },
  renders: STRINGS,
  deviations: STRINGS,
  openIssues: STRINGS,
}
const IMPL = { type: 'object', properties: IMPL_PROPERTIES, required: Object.keys(IMPL_PROPERTIES) }
const FIX = {
  type: 'object',
  properties: {
    ...IMPL_PROPERTIES,
    fixed: STRINGS,
    rejected: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, evidence: { type: 'string' } }, required: ['id', 'evidence'] } },
  },
  required: [...Object.keys(IMPL_PROPERTIES), 'fixed', 'rejected'],
}
const REVIEW = {
  type: 'object',
  properties: {
    findings: {
      type: 'array',
      items: {
        type: 'object',
        properties: {
          id: { type: 'string' },
          severity: { type: 'string', enum: ['blocker', 'major', 'minor'] },
          file: { type: 'string' },
          line: { type: 'integer' },
          claim: { type: 'string' },
          evidence: { type: 'string' },
          fix: { type: 'string' },
        },
        required: ['id', 'severity', 'file', 'line', 'claim', 'evidence', 'fix'],
      },
    },
  },
  required: ['findings'],
}
const GATE = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['passed', 'failed', 'blocked'] },
    summary: { type: 'string' },
    commands: {
      type: 'array',
      items: { type: 'object', properties: { command: { type: 'string' }, exitCode: { type: 'integer' }, excerpt: { type: 'string' } }, required: ['command', 'exitCode', 'excerpt'] },
    },
  },
  required: ['status', 'summary', 'commands'],
}

function options(role, extra) {
  return { ...extra, ...(CONFIG.agents[role] || {}) }
}

function block(record, reason) {
  record.status = 'blocked'
  record.reason = reason
  log(`${record.milestone} blocked: ${reason}`)
  return record
}

function actionableFindings(findings, round) {
  if (CONFIG.minorFindings === 'always') return findings
  if (CONFIG.minorFindings === 'first-round' && round === 0) return findings
  return findings.filter(finding => finding.severity !== 'minor')
}

function gatePrompt(header, report) {
  return `${header}

You are the independent gate for this milestone. Do not edit, format, or generate any file; only run checks.
Run these checks exactly:
${fill(CONFIG.gate.instructions)}

Also run the focused tests the writer reported:
${report.focusedTests || '(none reported)'}

Return status "passed" only when every command exited 0. Return "failed" when a check fails, with the failing excerpt. Return "blocked" when the environment prevents running a check (toolchain, simulator, signing, missing configuration, or a hang you had to kill).`
}

function reviewPrompt(header, lens, report, gate, rejected) {
  const previous = rejected.length
    ? `\n\nThe writer rejected these earlier findings with evidence. Report one again, under a new id, only if the evidence is wrong:\n${JSON.stringify(rejected, null, 2)}`
    : ''
  return `${header}

You are an independent reviewer of this milestone. ${CONFIG.reviewerInstructions}

${fill(CONFIG.lenses[lens])}

Writer report:
${JSON.stringify(report, null, 2)}

Gate result:
${JSON.stringify(gate, null, 2)}${previous}`
}

async function runMilestone(milestone) {
  phase(milestone.id)
  const record = { milestone: milestone.id, status: 'running', rounds: [] }
  const header = `${SHARED}\n\nMILESTONE ${milestone.title}\n\n${fill(milestone.brief)}`
  const impl = await agent(`${header}\n\nYou are the only writer for this milestone. ${CONFIG.writerInstructions}\nReturn the structured report.`, options('implement', { label: `${milestone.id}:implement`, phase: milestone.id, schema: IMPL }))
  record.impl = impl
  if (!impl) return block(record, 'the writer returned no result')
  if (impl.status !== 'done') return block(record, `the writer reported ${impl.status}: ${impl.openIssues.join('; ') || impl.summary}`)
  let current = impl
  let rejected = []
  for (let round = 0; ; round++) {
    const entry = { round }
    record.rounds.push(entry)
    let gate = null
    if (CONFIG.gate) {
      gate = await agent(gatePrompt(header, current), options('gate', { label: `${milestone.id}:gate-r${round}`, phase: milestone.id, schema: GATE }))
      entry.gate = gate
      if (!gate) return block(record, `the gate returned no result in round ${round}`)
      if (gate.status === 'blocked') return block(record, `the gate was blocked in round ${round}: ${gate.summary}`)
    }
    let actionable
    if (gate && gate.status === 'failed') {
      actionable = [{ id: `gate-r${round}`, lens: 'gate', severity: 'blocker', claim: 'The gate failed.', evidence: `${gate.summary}\n${JSON.stringify(gate.commands, null, 2)}`, fix: 'Repair only failures this milestone caused; keep the gates and tests as they are.' }]
      log(`${milestone.id} r${round}: gate failed`)
    } else {
      const reviews = await parallel(milestone.lenses.map(lens => () => agent(reviewPrompt(header, lens, current, gate, rejected), options('review', { label: `${milestone.id}:review-${lens}-r${round}`, phase: milestone.id, schema: REVIEW }))))
      const missing = milestone.lenses.filter((lens, index) => !reviews[index])
      if (missing.length) return block(record, `review missing for lens ${missing.join(', ')} in round ${round}`)
      const findings = reviews.flatMap((review, index) => review.findings.map((finding, position) => ({ ...finding, id: `${milestone.lenses[index]}:${finding.id}:${position}`, lens: milestone.lenses[index] })))
      entry.findings = findings
      actionable = actionableFindings(findings, round)
      const deferred = findings.filter(finding => !actionable.includes(finding))
      entry.deferred = deferred
      const count = severity => findings.filter(finding => finding.severity === severity).length
      log(`${milestone.id} r${round}: ${findings.length} findings (${count('blocker')}B/${count('major')}M/${count('minor')}m)${deferred.length ? `; ${deferred.length} minor deferred by policy` : ''}`)
    }
    if (!actionable.length) {
      record.status = 'completed'
      record.final = current
      return record
    }
    if (round >= CONFIG.maxRepairs) return block(record, `${actionable.length} actionable findings remain after ${CONFIG.maxRepairs} repairs: ${actionable.map(finding => finding.id).join(', ')}`)
    const fix = await agent(`${header}

You own milestone ${milestone.title} now as its only writer. Verify each finding against the code. Fix the real ones and list their ids in "fixed". Reject false ones in "rejected" with file:line evidence. Every id below must appear in exactly one of the two lists. ${CONFIG.writerInstructions}

Previous report:
${JSON.stringify(current, null, 2)}

Findings:
${JSON.stringify(actionable, null, 2)}`, options('fix', { label: `${milestone.id}:fix-r${round + 1}`, phase: milestone.id, schema: FIX }))
    entry.fix = fix
    if (!fix) return block(record, `the repair writer returned no result in round ${round + 1}`)
    if (fix.status !== 'done') return block(record, `the repair writer reported ${fix.status}: ${fix.openIssues.join('; ') || fix.summary}`)
    const ids = actionable.map(finding => finding.id)
    const fixed = new Set(fix.fixed)
    const rejectedIds = new Set(fix.rejected.map(item => item.id))
    const unaccounted = ids.filter(id => !fixed.has(id) && !rejectedIds.has(id))
    const doubled = ids.filter(id => fixed.has(id) && rejectedIds.has(id))
    if (unaccounted.length || doubled.length) return block(record, `the repair report must list each finding once in fixed or rejected; missing ${unaccounted.join(', ') || 'none'}, both ${doubled.join(', ') || 'none'}`)
    rejected = fix.rejected.flatMap(item => {
      const finding = actionable.find(candidate => candidate.id === item.id)
      return finding && finding.lens !== 'gate' ? [{ ...finding, rejection: item.evidence }] : []
    })
    current = fix
  }
}

const results = []
for (const [index, milestone] of CONFIG.milestones.entries()) {
  const result = await runMilestone(milestone)
  results.push(result)
  if (result.status !== 'completed') {
    const notRun = CONFIG.milestones.slice(index + 1).map(item => item.id)
    if (notRun.length) log(`Halting after ${milestone.id}. Not run: ${notRun.join(', ')}`)
    break
  }
}

const completed = results.filter(result => result.status === 'completed').map(result => result.milestone)
let finalCheck = null
let critic = null
if (CONFIG.final.tester && completed.length) {
  phase('Final')
  finalCheck = await agent(`${SHARED}\n\nYou are the final tester for milestones ${completed.join(', ')}. Change product code only when a check fails because of this work, and list any such fix.\n${fill(CONFIG.final.tester)}\nReturn the structured report.`, options('final', { label: 'final:test', phase: 'Final', schema: IMPL }))
}
if (CONFIG.final.critic) {
  phase('Final')
  critic = await agent(`${SHARED}\n\nYou are the completeness critic. Do not build or edit. ${fill(CONFIG.final.critic)}\n\nMilestone results:\n${JSON.stringify(results.map(result => ({ milestone: result.milestone, status: result.status, reason: result.reason, final: result.final })), null, 2)}\n\nFinal test report:\n${JSON.stringify(finalCheck, null, 2)}`, options('critic', { label: 'final:critic', phase: 'Final' }))
}
const allCompleted = results.length === CONFIG.milestones.length && results.every(result => result.status === 'completed')
const finalPassed = !CONFIG.final.tester || (finalCheck !== null && finalCheck.status === 'done')
return { status: allCompleted && finalPassed ? 'completed' : 'blocked', milestones: results, finalCheck, critic }
